// AL5 / AL6 – Préparer l'affichage à partir des mesures (S2), des alertes (AL2) et des événements.
// Entrées : pce92/mesures/<node_id>, pce92/alertes/<node_id> (moteur de B2, quand il sera prêt),
//           pce92/evenements, et un « tic » toutes les 30 s.
// Sorties : 1. vue simple (AL5)  2. vue technique (AL6)  3. courbe du niveau  4. courbe de la batterie
// Les dates sont envoyées en ISO (UTC) et mises en forme dans le navigateur : les textes et les courbes
// affichent ainsi la même heure, celle de l'appareil qui consulte (Paris pour l'équipe, Thiès sur place).

// --- Réglages provisoires (à remplacer par le fichier de seuils et de sites de B2, AL1) ---
const SITES = { 3: "Site de test (nœud 3)" };
// Seuils des paliers, en mm au-dessus du sol. Par défaut : jaune = marge critique du contrat (100 mm),
// rouge = repère de danger du contrat (300 mm), orange = valeur intermédiaire PROVISOIRE.
const SEUILS_DEFAUT = { jaune: 100, orange: 200, rouge: 300 };
const SEUILS_PAR_SITE = {};      // ex. { 3: { jaune: 120, orange: 250, rouge: 400 } }
const TENDANCE_MM = 20;          // écart minimal pour parler de hausse ou de baisse
const BATT_FAIBLE_V = 3.2;       // contrat v1.2, périmètre V2 : batterie faible sous 3,20 V
// Libellés et actions par palier (repris du L1, partie 4.1.2), à faire valider par le client.
const PALIERS = {
    vert:   { rang: 0, libelle: "NORMAL",            action: "Surveillance : aucune action." },
    jaune:  { rang: 1, libelle: "VIGILANCE JAUNE",   action: "Informer : suivre l'évolution du niveau." },
    orange: { rang: 2, libelle: "ALERTE ORANGE",     action: "Prévenir les zones à risque et pré-positionner les secours." },
    rouge:  { rang: 3, libelle: "ALERTE ROUGE",      action: "Évacuer les zones inondables. Appeler les secours." },
    indisponible: { rang: -1, libelle: "DONNÉES INDISPONIBLES",
                    action: "Aucune mesure exploitable : la situation réelle est inconnue. Vérifier le capteur." }
};
// ------------------------------------------------------------------------------------------

const etats = flow.get("etats") || {};          // dernier état connu par capteur
const alertes = flow.get("alertes") || {};      // dernier palier reçu du moteur de B2, par capteur
const compteurs = flow.get("compteurs") || { perdues: 0, doublons: 0, rejets: 0, retours_seq: 0 };
let evenements = flow.get("evenements") || [];  // 10 derniers événements
const sorties = [null, null, null, null];

function nomSite(id) { return SITES[id] || ("Capteur n° " + id); }
function seuils(id) { return SEUILS_PAR_SITE[id] || SEUILS_DEFAUT; }
function palierParHauteur(mm, s) {
    if (mm >= s.rouge) return "rouge";
    if (mm >= s.orange) return "orange";
    if (mm >= s.jaune) return "jaune";
    return "vert";
}

// 1. Une nouvelle mesure
if (msg.topic && msg.topic.startsWith("pce92/mesures/")) {
    const m = msg.payload;
    const e = etats[m.node_id] || { node_id: m.node_id };
    if (m.water_valid) {
        e.precedent_mm = e.dernier_valide ? e.dernier_valide.water_mm : null;
        e.dernier_valide = m;
    }
    e.derniere = m;
    // Heure d'arrivée dans Node-RED (sert à repérer un capteur muet). Pour l'historique
    // rechargé depuis la base (S3), on reprend l'heure de réception d'origine.
    e.arrivee = msg.replay ? Date.parse(m.received_at) : Date.now();
    etats[m.node_id] = e;
    const x = Date.parse(m.received_at);
    const nom = nomSite(m.node_id);
    const s = seuils(m.node_id);
    const niveau = [];
    const batterie = [];
    // Trames perdues juste avant : on coupe la courbe (point vide au milieu du trou),
    // pour ne pas tracer une ligne qui inventerait des mesures jamais reçues.
    if (m.lost_before > 0) {
        const xTrou = x - ((m.next_min || 30) * 60000) / 2;
        niveau.push({ topic: nom, payload: { x: xTrou, y: null } });
        batterie.push({ topic: nom, payload: { x: xTrou, y: null } });
    }
    // Les seuils d'abord (couleurs fixes : rouge, orange, jaune), puis la mesure.
    niveau.unshift({ topic: "Seuil rouge (" + s.rouge + " mm)", payload: { x: x, y: s.rouge } },
                   { topic: "Seuil orange (" + s.orange + " mm)", payload: { x: x, y: s.orange } },
                   { topic: "Seuil jaune (" + s.jaune + " mm)", payload: { x: x, y: s.jaune } });
    // Mesure invalide (0xFFFF) : point vide, la courbe est coupée à cet endroit.
    niveau.push({ topic: nom, payload: { x: x, y: m.water_valid ? m.water_mm : null } });
    batterie.push({ topic: nom, payload: { x: x, y: m.batt_v } });
    sorties[2] = niveau;
    sorties[3] = batterie;
    e.perdues = (e.perdues || 0) + (m.lost_before || 0);
    e.recues = (e.recues || 0) + 1;
}

// 2. Un palier calculé par le moteur d'alerte de B2 (AL2) : { node_id, palier, ... }
if (msg.topic && msg.topic.startsWith("pce92/alertes/")) {
    const a = msg.payload || {};
    if (PALIERS[a.palier] && a.palier !== "indisponible") {
        alertes[a.node_id] = { palier: a.palier, recu_a: new Date().toISOString() };
    }
}

// 3. Un événement (rejet, doublon, trames perdues, retour de seq)
if (msg.topic === "pce92/evenements") {
    const ev = msg.payload;
    if (ev.type === "doublon") compteurs.doublons += 1;
    if (ev.type === "rejet") compteurs.rejets += 1;
    if (ev.type === "retour_seq") compteurs.retours_seq += 1;
    const textes = {
        trames_perdues: (ev.nombre + " trame(s) perdue(s) avant la seq " + ev.seq),
        doublon: ("doublon écarté (seq " + ev.seq + ")"),
        rejet: ("trame rejetée : " + ev.raison),
        retour_seq: ("compteur revenu en arrière (" + ev.seq_precedent + " → " + ev.seq + ")")
    };
    evenements.unshift({ heure_iso: ev.received_at || new Date().toISOString(),
                         capteur: ev.node_id ?? "—", texte: textes[ev.type] || ev.type });
    evenements = evenements.slice(0, 10);
}

flow.set("etats", etats);
flow.set("alertes", alertes);
flow.set("compteurs", compteurs);
flow.set("evenements", evenements);

// 4. Recalculer les deux vues (à chaque message, y compris le tic de 30 s)
const sites = [], lignes = [];
let derniereReception = null;
for (const id of Object.keys(etats).sort((a, b) => a - b)) {
    const e = etats[id];
    const d = e.derniere;
    const v = e.dernier_valide;
    const periode = d.next_min || 60;
    const marge = Math.max(5, periode / 2);                   // tolérance de retard, en minutes
    // Capteur muet : aucune nouvelle trame n'est arrivée depuis next_min + marge.
    const muet = Date.now() > (e.arrivee || Date.parse(d.received_at)) + (periode + marge) * 60000;

    // Palier : moteur de B2 s'il a parlé, sinon calcul provisoire sur la hauteur + bit d'alerte du nœud.
    let palier, source;
    if (alertes[id]) {
        palier = alertes[id].palier; source = "moteur d'alerte";
    } else {
        palier = v ? palierParHauteur(v.water_mm, seuils(id)) : "vert";
        if (d.alert) palier = "rouge";                        // règle 3 : le bit d'alerte déclenche l'alerte
        source = "calcul provisoire";
    }
    // Sans mesure exploitable, pas de verdict : jamais de vert pour un capteur muet.
    const sansVerdict = muet || !d.water_valid;
    if (sansVerdict) palier = "indisponible";

    let tendance = "";
    if (!sansVerdict && v && e.precedent_mm !== null && e.precedent_mm !== undefined) {
        const diff = v.water_mm - e.precedent_mm;
        tendance = diff >= TENDANCE_MM ? "en hausse" : (diff <= -TENDANCE_MM ? "en baisse" : "stable");
    }

    sites.push({
        node_id: Number(id), nom: nomSite(id), palier: palier,
        rang: PALIERS[palier].rang, libelle: PALIERS[palier].libelle, action: PALIERS[palier].action,
        niveau: v ? Math.round(v.water_mm / 10) + " cm" : "—",
        ancien: sansVerdict ? (v ? "Dernier niveau connu : " + Math.round(v.water_mm / 10) + " cm" : "Aucun niveau connu") : "",
        ancien_iso: sansVerdict && v ? v.received_at : null,
        tendance: tendance,
        derniere_iso: d.received_at
    });
    lignes.push({
        nom: nomSite(id), palier: PALIERS[palier].libelle, source: sansVerdict ? "—" : source,
        etat: muet ? "en retard" : (d.water_valid ? "à jour" : "mesure invalide"),
        derniere_iso: d.received_at,
        prochaine_iso: d.expected_next_at,
        perdues: e.perdues || 0,
        reception: e.recues ? Math.round(100 * e.recues / (e.recues + (e.perdues || 0))) + " %" : "—",
        niveau: d.water_valid ? d.water_mm + " mm" : "invalide",
        bit: d.alert ? "levé" : "non",
        batterie: d.batt_v === null ? "inconnue" : d.batt_v.toFixed(2) + " V" + (d.batt_v < BATT_FAIBLE_V ? " (faible)" : ""),
        batt_faible: d.batt_v !== null && d.batt_v < BATT_FAIBLE_V,
        signal: (d.rssi ?? "—") + " dBm / " + (d.snr ?? "—") + " dB",
        seq: d.seq
    });
    if (!derniereReception || d.received_at > derniereReception) derniereReception = d.received_at;
}

// Total des trames perdues = somme par capteur (recalculée aussi après un redémarrage, grâce à S3).
compteurs.perdues = Object.values(etats).reduce((t, e) => t + (e.perdues || 0), 0);
sorties[0] = { payload: { sites: sites } };
sorties[1] = { payload: {
    capteurs: lignes, compteurs: compteurs, evenements: evenements,
    derniere_reception_iso: derniereReception
} };
return sorties;

// Efface l'état mémorisé et vide les deux courbes (utile avant une démonstration).
flow.set("etats", {});
flow.set("alertes", {});
flow.set("compteurs", { perdues: 0, doublons: 0, rejets: 0, retours_seq: 0 });
flow.set("evenements", []);
node.status({ fill: "blue", shape: "dot", text: "réinitialisé à " + new Date().toLocaleTimeString("fr-FR") });
return [{ payload: [] }, { topic: "tic" }];
